import{_ as r,o as e,c as s,a2 as o}from"./chunks/framework.BWuWLRhz.js";const u=JSON.parse('{"title":"서비스 상태","description":"","frontmatter":{},"headers":[],"relativePath":"ko-KR/user-guide/settings/service-status.md","filePath":"ko-KR/user-guide/settings/service-status.md","lastUpdated":1785993908000}'),a={name:"ko-KR/user-guide/settings/service-status.md"};function n(i,t,l,g,p,c){return e(),s("div",null,[...t[0]||(t[0]=[o('<h1 id="서비스-상태" tabindex="-1">서비스 상태 <a class="header-anchor" href="#서비스-상태" aria-label="Permalink to &quot;서비스 상태&quot;">​</a></h1><p>백그라운드 인덱싱 서비스를 관리하며, 그 로그의 실시간 뷰를 제공합니다.</p><h2 id="서비스-제어" tabindex="-1">서비스 제어 <a class="header-anchor" href="#서비스-제어" aria-label="Permalink to &quot;서비스 제어&quot;">​</a></h2><p>상태 카드는 상승된 권한의 인덱서의 현재 상태 — <strong>설치 중</strong>, <strong>인덱싱 중</strong>, <strong>준비됨</strong>(실시간 파일/폴더 수와 함께), 또는 <strong>오류</strong> — 를 그에 맞는 아이콘(스피너, 체크 표시, 또는 오류 배지)과 함께 보여줍니다.</p><p><strong>서비스 설치 및 시작</strong> 버튼은 서비스가 아직 설치되지 않았거나 오류가 발생했을 때만 나타납니다 — 일단 설치되어 실행 중이라면 이 페이지에는 수동 시작/중지/제거 컨트롤이 없습니다 — 서비스는 백그라운드에서 그냥 계속 실행되고 있을 것으로 예상됩니다.</p><h2 id="로그" tabindex="-1">로그 <a class="header-anchor" href="#로그" aria-label="Permalink to &quot;로그&quot;">​</a></h2><p>세 개의 탭 — <strong>App</strong>, <strong>Hook</strong>, <strong>Service</strong> — 은 Lertaro가 실행하는 세 프로세스(상승된 권한의 백그라운드 인덱서, 상호작용하는 사용자별 App, 키보드 훅 프로세스)에 대응합니다. 각 탭은 해당 프로세스의 로그 줄을 레벨별로 색상 코드화하여 보여줍니다.</p><ul><li><strong>레벨 필터</strong> 드롭다운 — All / Error / Warn / Info / Debug.</li><li><strong>검색 상자</strong> — 표시되는 줄을 키워드로 필터링하며, 레벨 필터와 함께 결합됩니다.</li><li><strong>지우기</strong> 버튼 — 현재 선택된 탭의 로그를 비웁니다. Service 탭의 로그를 지우는 것은 서비스 자체를 통해 이루어집니다(App 프로세스는 이를 직접 쓸 권한이 없습니다). App과 Hook 로그는 사용자별 파일이므로 직접 지워집니다.</li></ul><p>문제를 해결할 때 가장 먼저 확인해야 할 곳입니다 — 자세한 내용은 <a href="./../troubleshooting.html#그래도-해결되지-않는다면">문제 해결</a>을 참고하세요.</p>',9)])])}const _=r(a,[["render",n]]);export{u as __pageData,_ as default};
